package Question10;

class Shipping extends Payment { protected String shippingAddress; protected double shippingCost; public Shipping(int id, String storeName, String address, String email, String categoryName, String categoryCode, String productName, String productCode, double price, String customerName, String contactNumber, String addressCust, String orderDate, String orderId, String paymentMethod, String paymentStatus, String shippingAddress, double shippingCost){ super(id, storeName, address, email, categoryName, categoryCode, productName, productCode, price, customerName, contactNumber, addressCust, orderDate, orderId, paymentMethod, paymentStatus); this.shippingAddress = (shippingAddress!=null)?shippingAddress:addressCust; this.shippingCost = Math.max(0.0, shippingCost);} }
